INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G5.CONSER.SOIL_CONSERVATION.COMPOST_PIT', 'AGRI.G4.CONSER.SOIL_CONSERVATION.COMPOST_MAKING', 'skill', 'essential', 'A waste pit is filled and cared for like the Grade 4 compost heap. Proposed, to confirm by a CBC Agriculture teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
