INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G5.CONSER.SOIL_CONSERVATION.PLANT_REMAINS', 'AGRI.G4.CONSER.SOIL_CONSERVATION.COMPOST_MATERIALS', 'skill', 'essential', 'Plant remains are the main compost material named in Grade 4. Proposed, to confirm by a CBC Agriculture teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G5.CONSER.SOIL_CONSERVATION.PLANT_REMAINS', 'SCIE.G4.MATTER.MANAGEMENT_OF_SOLID_WAST.WASTE_CLASSIFY', 'skill', 'essential', 'Plant remains are decomposable waste that returns to the soil. Proposed, to confirm by a CBC Agriculture teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G5.CONSER.WATER_CONSERVATION.WATER_WAYS', 'AGRI.G4.CONSER.WATER_CONSERVATION.a', 'outcome', 'essential', 'Grade 4 Agriculture and Nutrition introduced it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G5.CONSER.WATER_CONSERVATION.WATER_WAYS', 'AGRI.G4.CONSER.WATER_CONSERVATION.DRIP_MEANING', 'skill', 'essential', 'Drip irrigation from Grade 4 is one way of saving garden water. Proposed, to confirm by a CBC Agriculture teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
