INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G5.PRODUC.REPAIRING_GARMENTS.STITCH_TYPES', 'AGRI.G4.PRODUC.MAKING_TACKING_STITCHES.TACK_TYPES', 'skill', 'essential', 'Grade 4 told tacking stitches apart by their length and spacing. Proposed, to confirm by a CBC Agriculture teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
