INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G5.PRODUC.REPAIRING_GARMENTS.SEAM_REPAIR', 'AGRI.G4.PRODUC.MAKING_TACKING_STITCHES.b', 'outcome', 'essential', 'Grade 4 Agriculture and Nutrition introduced it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G5.PRODUC.REPAIRING_GARMENTS.SEAM_REPAIR', 'AGRI.G4.PRODUC.MAKING_TACKING_STITCHES.TACK_USE', 'skill', 'essential', 'A gaping seam is tacked or pinned before it is restitched. Proposed, to confirm by a CBC Agriculture teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G5.PRODUC.CONSTRUCTING_INNOVATIVE_.GARDEN_TYPES', 'AGRI.G5.FOOD_P.GROWING_VEGETABLES.VEG_PRACTICES', 'skill', 'essential', 'This skill builds on it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G5.PRODUC.CONSTRUCTING_INNOVATIVE_.GARDEN_TYPES', 'ENVI.G3.RESOUR.PLANTS.c', 'outcome', 'essential', 'Grade 3 made a kitchen garden from local materials; innovative gardens build on it. Proposed, to confirm by a CBC Agriculture teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G5.PRODUC.CONSTRUCTING_INNOVATIVE_.GARDEN_BUILD', 'AGRI.G5.PRODUC.CONSTRUCTING_INNOVATIVE_.GARDEN_TYPES', 'skill', 'essential', 'This skill builds on it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G5.PRODUC.CONSTRUCTING_INNOVATIVE_.GARDEN_BUILD', 'AGRI.G5.FOOD_P.GROWING_VEGETABLES.VEG_PRACTICES', 'skill', 'essential', 'This skill builds on it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.SOIL_CONSERVATION.SOIL_SITES.M_AG_SITE_DARK', 'AGRI.G5.CONSER.SOIL_CONSERVATION.SOIL_SITES', 'Judges soil quality by colour alone (thinks dark soil is poor and pale soil is rich).', '{"question":"Which soil is likely to be poor for growing crops?","wrong_answer":"Dark, crumbly soil full of rotted leaves","correct_answer":"Pale, hard soil with no plants and gullies"}'::jsonb, 'The child links dark with dirty or burnt and pale with clean.', 'Offer "Dark, crumbly soil full of rotted leaves" next to the right answer and ask the question again in a new context.', 'Show two soils: dark crumbly and pale packed. Ask which holds water and which grows a seed, then ask what the colour tells.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.SOIL_CONSERVATION.SOIL_SITES.M_AG_SITE_PIT_LOW', 'AGRI.G5.CONSER.SOIL_CONSERVATION.SOIL_SITES', 'Digs the waste pit anywhere (in a hollow where rain collects, or beside the borehole).', '{"question":"Where is the best place for the school organic waste pit?","wrong_answer":"In the low place where rain water collects","correct_answer":"On firm higher ground near the garden, away from the well"}'::jsonb, 'The child thinks wet ground helps waste to rot and does not think about drinking water.', 'Offer "In the low place where rain water collects" next to the right answer and ask the question again in a new context.', 'Walk the site after rain. Ask what happens to a pit that fills with water, and what could happen to a nearby well.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.SOIL_CONSERVATION.SOIL_SITES.M_AG_SITE_BARE_FINE', 'AGRI.G5.CONSER.SOIL_CONSERVATION.SOIL_SITES', 'Thinks a bare patch is just normal ground that needs no help.', '{"question":"The playground edge is hard and bare and crops there turn yellow and stay small. What is this a sign of?","wrong_answer":"The ground is normal and needs nothing","correct_answer":"The soil is poor and needs improving"}'::jsonb, 'The child has seen bare ground all their life and does not read it as a problem.', 'Offer "The ground is normal and needs nothing" next to the right answer and ask the question again in a new context.', 'Plant the same seed in a bare patch and in the garden and compare after two weeks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.SOIL_CONSERVATION.COMPOST_PIT.M_AG_PIT_ANYTHING', 'AGRI.G5.CONSER.SOIL_CONSERVATION.COMPOST_PIT', 'Puts any rubbish in the organic waste pit (polythene, tins, glass).', '{"question":"Which of these should NOT go into an organic waste pit?","wrong_answer":"A polythene bag","correct_answer":"Banana peelings"}'::jsonb, 'The child thinks a pit is a general rubbish pit.', 'Offer "A polythene bag" next to the right answer and ask the question again in a new context.', 'Dig up an old pit with a teacher. Ask what rotted and what did not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.SOIL_CONSERVATION.COMPOST_PIT.M_AG_PIT_COOKED', 'AGRI.G5.CONSER.SOIL_CONSERVATION.COMPOST_PIT', 'Thinks cooked food, meat and bones are good for the pit.', '{"question":"Why do we keep leftover meat and oily food out of the organic waste pit?","wrong_answer":"They are the best food for the pit","correct_answer":"They draw rats and flies and smell"}'::jsonb, 'The child knows meat rots and so thinks it belongs.', 'Offer "They are the best food for the pit" next to the right answer and ask the question again in a new context.', 'Ask what comes to a rubbish heap with meat scraps. Then say what a pit for a school garden should attract.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.SOIL_CONSERVATION.COMPOST_PIT.M_AG_PIT_NO_CARE', 'AGRI.G5.CONSER.SOIL_CONSERVATION.COMPOST_PIT', 'Fills the pit once and never wets, turns or covers it.', '{"question":"After the pit is filled, what should the school do?","wrong_answer":"Leave it dry and open for the whole year","correct_answer":"Keep it damp and covered and wait for it to rot"}'::jsonb, 'The child thinks rotting happens by itself.', 'Offer "Leave it dry and open for the whole year" next to the right answer and ask the question again in a new context.', 'Compare a damp covered heap and a dry open heap after a month.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.SOIL_CONSERVATION.PLANT_REMAINS.M_AG_REMAINS_BURN', 'AGRI.G5.CONSER.SOIL_CONSERVATION.PLANT_REMAINS', 'Thinks burning plant remains is the best way to clear them.', '{"question":"After harvest, a farmer burns the maize stalks. What does the soil lose?","wrong_answer":"Nothing, burning is best","correct_answer":"The humus and plant food the stalks would have given"}'::jsonb, 'Burning is the common way of clearing and the child has seen ash on the field.', 'Offer "Nothing, burning is best" next to the right answer and ask the question again in a new context.', 'Ask what the soil would receive if the stalks were rotted or dug in.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.SOIL_CONSERVATION.PLANT_REMAINS.M_AG_REMAINS_WASTE', 'AGRI.G5.CONSER.SOIL_CONSERVATION.PLANT_REMAINS', 'Calls plant remains rubbish with no use.', '{"question":"What is a good use of the leaves and grass cleared from the school compound?","wrong_answer":"Throw them away on the road","correct_answer":"Make compost or spread them as mulch"}'::jsonb, 'The child sees cleared leaves as waste to get rid of.', 'Offer "Throw them away on the road" next to the right answer and ask the question again in a new context.', 'Ask where forest soil gets its food from, then link to fallen leaves.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.SOIL_CONSERVATION.SOIL_SITES.M_AG5_SITE_PLANTS', 'AGRI.G5.CONSER.SOIL_CONSERVATION.SOIL_SITES', 'Thinks soil where weeds grow thickly is always poor and needs improving.', '{"question":"Thick green weeds grow in one corner of the school. What does this say about the soil?","wrong_answer":"The soil there is poor","correct_answer":"The soil there is likely fertile and moist"}'::jsonb, 'The child sees weeds as a sign of a neglected, bad place.', 'Offer "The soil there is poor" next to the right answer and ask the question again in a new context.', 'Compare the weedy corner with a bare hard patch: which soil is dark and soft when dug?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.SOIL_CONSERVATION.COMPOST_PIT.M_AG5_PIT_DEEP', 'AGRI.G5.CONSER.SOIL_CONSERVATION.COMPOST_PIT', 'Thinks the deeper the pit, the better, even if it fills with water.', '{"question":"Why is an organic waste pit not dug in a waterlogged place?","wrong_answer":"Water helps the waste rot faster","correct_answer":"The pit fills with water, the waste rots badly and smells"}'::jsonb, 'The child knows rotting needs water and does not see that too much water stops air reaching it.', 'Offer "Water helps the waste rot faster" next to the right answer and ask the question again in a new context.', 'Compare a jar of leaves just damp with one under water after two weeks: smell and look.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.SOIL_CONSERVATION.PLANT_REMAINS.M_AG5_REM_FRESH', 'AGRI.G5.CONSER.SOIL_CONSERVATION.PLANT_REMAINS', 'Thinks fresh plant remains feed the crop the moment they are put on the soil.', '{"question":"Maize stalks are laid on the soil. When do they feed the soil?","wrong_answer":"At once, the same day","correct_answer":"Slowly, as they rot over weeks and months"}'::jsonb, 'The child thinks of plant remains like fertiliser poured on.', 'Offer "At once, the same day" next to the right answer and ask the question again in a new context.', 'Look at mulch laid last term: what has happened to the bottom layer?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.SOIL_CONSERVATION.PLANT_REMAINS.M_AG5_REM_ANIMALS', 'AGRI.G5.CONSER.SOIL_CONSERVATION.PLANT_REMAINS', 'Thinks plant remains are only good as animal feed and give the soil nothing.', '{"question":"Which is a use of plant remains for soil improvement?","wrong_answer":"Only feeding them to cattle","correct_answer":"Using them as mulch or compost"}'::jsonb, 'In many homes stover goes to the animals, so the child sees no other use.', 'Offer "Only feeding them to cattle" next to the right answer and ask the question again in a new context.', 'Ask what happens to the soil under a mulch of dry grass in the dry season.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.WATER_CONSERVATION.WATER_WAYS.M_AG_WATER_NOON', 'AGRI.G5.CONSER.WATER_CONSERVATION.WATER_WAYS', 'Thinks midday is the best time to water because it is hot and the plants are thirsty.', '{"question":"When is it best to water a garden to save water?","wrong_answer":"At midday when the sun is hottest","correct_answer":"Early in the morning or in the evening"}'::jsonb, 'The child links heat with thirst.', 'Offer "At midday when the sun is hottest" next to the right answer and ask the question again in a new context.', 'Pour a cup of water on the ground at noon and one at six in the evening and compare how long each stays damp.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.WATER_CONSERVATION.WATER_WAYS.M_AG_WATER_MULCH_WARM', 'AGRI.G5.CONSER.WATER_CONSERVATION.WATER_WAYS', 'Thinks mulch is for keeping plants warm or for feeding them, not for keeping water in.', '{"question":"What does a layer of dry grass around kale do for the water in the soil?","wrong_answer":"It keeps the plants warm at night","correct_answer":"It slows the drying of the soil"}'::jsonb, 'The child knows a cover keeps something warm.', 'Offer "It keeps the plants warm at night" next to the right answer and ask the question again in a new context.', 'Uncover a mulched patch and a bare patch at midday and feel both.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.WATER_CONSERVATION.WATER_WAYS.M_AG_WATER_MORE', 'AGRI.G5.CONSER.WATER_CONSERVATION.WATER_WAYS', 'Thinks the only way to help a dry garden is to use more water.', '{"question":"A garden dries out quickly. Which action saves water?","wrong_answer":"Pouring much more water on it each day","correct_answer":"Covering the soil with a layer of dry grass"}'::jsonb, 'The child links dry with more water.', 'Offer "Pouring much more water on it each day" next to the right answer and ask the question again in a new context.', 'Ask where the water went. Then show that a cover stops it escaping.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.WATER_CONSERVATION.MULCH_TEST.M_AG_TEST_UNFAIR', 'AGRI.G5.CONSER.WATER_CONSERVATION.MULCH_TEST', 'Changes more than one thing in a test (different crop or different water).', '{"question":"To test mulch, Otieno gives the mulched bed less water and plants beans there and kale in the other bed. What is wrong?","wrong_answer":"Nothing is wrong, this is fair","correct_answer":"More than one thing differs, so the result tells nothing"}'::jsonb, 'The child wants to help the mulched bed or does not know what a fair test is.', 'Offer "Nothing is wrong, this is fair" next to the right answer and ask the question again in a new context.', 'Ask what Otieno could blame if the mulched bed did better.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.WATER_CONSERVATION.MULCH_TEST.M_AG_TEST_RESULT', 'AGRI.G5.CONSER.WATER_CONSERVATION.MULCH_TEST', 'Expects the mulched bed to dry faster.', '{"question":"After a week of sun, which bed will stay damp longer, the mulched one or the bare one?","wrong_answer":"The bare one","correct_answer":"The mulched one"}'::jsonb, 'The child thinks a cover traps heat and dries soil.', 'Offer "The bare one" next to the right answer and ask the question again in a new context.', 'Do the test: dig a finger deep in both beds and feel.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.WATER_CONSERVATION.WATER_WAYS.M_AG5_WAT_GREY', 'AGRI.G5.CONSER.WATER_CONSERVATION.WATER_WAYS', 'Thinks used washing water can never be used in the garden.', '{"question":"Which water can be reused on garden plants?","wrong_answer":"None, garden water must be fresh","correct_answer":"Water left after washing vegetables or rinsing, without strong soap"}'::jsonb, 'The child thinks used water is dirty and harmful to everything.', 'Offer "None, garden water must be fresh" next to the right answer and ask the question again in a new context.', 'Pour vegetable-washing water on a bed and watch the plants over a week.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.WATER_CONSERVATION.MULCH_TEST.M_AG5_TEST_SURFACE', 'AGRI.G5.CONSER.WATER_CONSERVATION.MULCH_TEST', 'Judges the soil only by its top crust, so the bare bed looks as damp as the mulched one after rain.', '{"question":"How should you check how damp the soil is in the mulching test?","wrong_answer":"Look at the top of the soil","correct_answer":"Push a finger or a stick a few centimetres into the soil and feel"}'::jsonb, 'The child trusts what is seen on the surface.', 'Offer "Look at the top of the soil" next to the right answer and ask the question again in a new context.', 'Dig a finger into both beds two days after watering: the bare one is dry below the crust.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.WATER_CONSERVATION.MULCH_TEST.M_AG5_TEST_ONEDAY', 'AGRI.G5.CONSER.WATER_CONSERVATION.MULCH_TEST', 'Reads the result after one day and calls it final.', '{"question":"When should the results of a mulching test be read?","wrong_answer":"After one day","correct_answer":"After several days, checking each day"}'::jsonb, 'The child wants a quick answer and does not see that change takes time.', 'Offer "After one day" next to the right answer and ask the question again in a new context.', 'Show the record sheet: on day one both beds feel the same, by day five they differ.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.CONSERVING_WILD_ANIMALS.PEST_DAMAGE.M_AG_PEST_MIX', 'AGRI.G5.CONSER.CONSERVING_WILD_ANIMALS.PEST_DAMAGE', 'Mixes up which animal does which damage.', '{"question":"Which wild animal digs up sweet potatoes and cassava from the ground?","wrong_answer":"A quelea bird","correct_answer":"A warthog"}'::jsonb, 'The child knows pests only as a list of names.', 'Offer "A quelea bird" next to the right answer and ask the question again in a new context.', 'Ask where a bird can reach and where a digger can reach.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.CONSERVING_WILD_ANIMALS.PEST_DAMAGE.M_AG_PEST_ALL', 'AGRI.G5.CONSER.CONSERVING_WILD_ANIMALS.PEST_DAMAGE', 'Thinks every wild animal is an enemy of the farmer.', '{"question":"Which wild creature helps a farmer?","wrong_answer":"A bee that visits the flowers","correct_answer":"A monkey in the maize"}'::jsonb, 'The child sorts the whole of nature into harmful and not harmful.', 'Offer "A bee that visits the flowers" next to the right answer and ask the question again in a new context.', 'Ask what bees do to the flowers on a tomato plant and what owls do to rats.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.CONSERVING_WILD_ANIMALS.REPEL_METHODS.M_AG_REPEL_KILL', 'AGRI.G5.CONSER.CONSERVING_WILD_ANIMALS.REPEL_METHODS', 'Thinks poisoning or killing the animals is the answer.', '{"question":"Monkeys keep eating the maize. What is the best thing to do?","wrong_answer":"Poison them","correct_answer":"Use a scarecrow, noise makers or a guard to scare them away"}'::jsonb, 'The child sees only the loss and wants it to stop.', 'Offer "Poison them" next to the right answer and ask the question again in a new context.', 'Ask what happens to other animals that eat the poison and what the law says about wild animals.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.CONSERVING_WILD_ANIMALS.REPEL_METHODS.M_AG_REPEL_ONE', 'AGRI.G5.CONSER.CONSERVING_WILD_ANIMALS.REPEL_METHODS', 'Thinks one method suits every animal (a scarecrow for elephants).', '{"question":"Which is more likely to keep elephants off a farm?","wrong_answer":"A scarecrow made of old clothes","correct_answer":"A fence with beehives or chilli"}'::jsonb, 'The child learned one method and applies it to every pest.', 'Offer "A scarecrow made of old clothes" next to the right answer and ask the question again in a new context.', 'Ask whether an elephant is afraid of a coat on a stick.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.CONSERVING_WILD_ANIMALS.REPEL_METHODS.M_AG_REPEL_CLOSE', 'AGRI.G5.CONSER.CONSERVING_WILD_ANIMALS.REPEL_METHODS', 'Would go close to chase away a big animal.', '{"question":"A buffalo comes into the shamba at dusk. What should a child do?","wrong_answer":"Run at it and shout","correct_answer":"Stay away and tell an adult or the Kenya Wildlife Service"}'::jsonb, 'The child is brave but does not see the danger.', 'Offer "Run at it and shout" next to the right answer and ask the question again in a new context.', 'Ask who gets hurt when a person meets a frightened buffalo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.CONSERVING_WILD_ANIMALS.PEST_DAMAGE.M_AG5_DMG_MONKEY', 'AGRI.G5.CONSER.CONSERVING_WILD_ANIMALS.PEST_DAMAGE', 'Thinks baboons and monkeys harm only fruit trees and never other crops or property.', '{"question":"What damage can baboons do on a farm?","wrong_answer":"Only eat fruit","correct_answer":"Uproot and eat maize, eat fruit and break into stores"}'::jsonb, 'The child has seen monkeys in fruit trees only.', 'Offer "Only eat fruit" next to the right answer and ask the question again in a new context.', 'Show a picture of a maize field after baboons; ask what was eaten.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.CONSERVING_WILD_ANIMALS.PEST_DAMAGE.M_AG5_DMG_NIGHT', 'AGRI.G5.CONSER.CONSERVING_WILD_ANIMALS.PEST_DAMAGE', 'Thinks damage found in the morning was done by domestic animals, because wild animals come only by day.', '{"question":"Crops are found eaten in the morning with holes under the fence. Who could have done it?","wrong_answer":"Only the neighbour''s goats in the day","correct_answer":"A wild animal such as a porcupine at night"}'::jsonb, 'The child does not know many wild animals feed at night.', 'Offer "Only the neighbour''s goats in the day" next to the right answer and ask the question again in a new context.', 'Show tracks and a porcupine quill near a damaged plot.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.CONSER.CONSERVING_WILD_ANIMALS.REPEL_METHODS.M_AG5_REP_FIRE', 'AGRI.G5.CONSER.CONSERVING_WILD_ANIMALS.REPEL_METHODS', 'Thinks setting the bush on fire is a good way to chase wild animals away.', '{"question":"Is burning the bush a good way to repel wild animals?","wrong_answer":"Yes, it chases them away","correct_answer":"No, it destroys their home, the soil and can burn farms and people"}'::jsonb, 'The child sees the animals run from fire and thinks it works.', 'Offer "Yes, it chases them away" next to the right answer and ask the question again in a new context.', 'Ask what else the fire burns: grass for cattle, trees, homes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.GROWING_VEGETABLES.VEG_PRACTICES.M_AG_VEG_ORDER', 'AGRI.G5.FOOD_P.GROWING_VEGETABLES.VEG_PRACTICES', 'Puts the practices in the wrong order (transplants before the nursery, sows before preparing).', '{"question":"Which is the correct order?","wrong_answer":"Transplant, make a nursery, sow, harvest","correct_answer":"Prepare the land, make a nursery, sow, transplant, harvest"}'::jsonb, 'The child remembers the words but not how one practice depends on another.', 'Offer "Transplant, make a nursery, sow, harvest" next to the right answer and ask the question again in a new context.', 'Ask what you transplant if you have not sown.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.GROWING_VEGETABLES.VEG_PRACTICES.M_AG_VEG_WATER_ONLY', 'AGRI.G5.FOOD_P.GROWING_VEGETABLES.VEG_PRACTICES', 'Thinks growing vegetables means only sowing and watering.', '{"question":"What else must be done after transplanting kale?","wrong_answer":"Nothing, only watering is needed","correct_answer":"Weeding, mulching and controlling pests"}'::jsonb, 'The child has not seen a garden through to harvest.', 'Offer "Nothing, only watering is needed" next to the right answer and ask the question again in a new context.', 'Compare a weeded and an unweeded bed after three weeks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.GROWING_VEGETABLES.NURSERY_BED.M_AG_NURS_COARSE', 'AGRI.G5.FOOD_P.GROWING_VEGETABLES.NURSERY_BED', 'Leaves big lumps in the nursery bed.', '{"question":"Why is the nursery soil broken to a fine crumb?","wrong_answer":"Big lumps are better for tiny seeds","correct_answer":"Tiny seeds and roots need fine soil to touch"}'::jsonb, 'The child thinks a rough bed saves work.', 'Offer "Big lumps are better for tiny seeds" next to the right answer and ask the question again in a new context.', 'Hide a tiny seed under a lump and under a crumb and ask which one can push through.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.GROWING_VEGETABLES.NURSERY_BED.M_AG_NURS_DEEP', 'AGRI.G5.FOOD_P.GROWING_VEGETABLES.NURSERY_BED', 'Buries tiny seeds deep.', '{"question":"How deep should you cover tiny kale seeds?","wrong_answer":"About 10 cm deep","correct_answer":"Very thinly, about a finger nail deep"}'::jsonb, 'The child thinks deeper is safer.', 'Offer "About 10 cm deep" next to the right answer and ask the question again in a new context.', 'Ask how a tiny shoot can push through a thick layer of soil.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.GROWING_VEGETABLES.NURSERY_BED.M_AG_NURS_FLOOD', 'AGRI.G5.FOOD_P.GROWING_VEGETABLES.NURSERY_BED', 'Floods the bed with water or builds it on ground that holds water.', '{"question":"How should the nursery bed be watered?","wrong_answer":"Soaked heavily until water stands","correct_answer":"Lightly in the morning and evening on well-drained ground"}'::jsonb, 'The child thinks wet is better for seeds.', 'Offer "Soaked heavily until water stands" next to the right answer and ask the question again in a new context.', 'Ask what happens to tiny seeds in a puddle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.GROWING_VEGETABLES.SEEDLING_CARE.M_AG_TRANS_NOON', 'AGRI.G5.FOOD_P.GROWING_VEGETABLES.SEEDLING_CARE', 'Transplants at midday in full sun.', '{"question":"When is it best to transplant seedlings?","wrong_answer":"At midday in the sun","correct_answer":"In the evening or on a cloudy day"}'::jsonb, 'The child sees no difference between times of the day.', 'Offer "At midday in the sun" next to the right answer and ask the question again in a new context.', 'Place one wilted and one shaded seedling in the sun and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.GROWING_VEGETABLES.SEEDLING_CARE.M_AG_TRANS_DRY', 'AGRI.G5.FOOD_P.GROWING_VEGETABLES.SEEDLING_CARE', 'Pulls seedlings from dry soil with the roots bare.', '{"question":"What should you do before lifting seedlings from the nursery?","wrong_answer":"Leave the bed dry so the soil falls off","correct_answer":"Water the bed so the seedlings lift with soil on their roots"}'::jsonb, 'The child thinks clean roots are neater.', 'Offer "Leave the bed dry so the soil falls off" next to the right answer and ask the question again in a new context.', 'Ask which seedlings keep their roots: one pulled dry or one lifted wet with soil.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.GROWING_VEGETABLES.SEEDLING_CARE.M_AG_TRANS_NOWATER', 'AGRI.G5.FOOD_P.GROWING_VEGETABLES.SEEDLING_CARE', 'Thinks no care is needed after transplanting.', '{"question":"What is done after transplanting seedlings?","wrong_answer":"Nothing until harvest","correct_answer":"Firm the soil, water and shade them for a few days"}'::jsonb, 'The child thinks the job ends when the seedling is in the ground.', 'Offer "Nothing until harvest" next to the right answer and ask the question again in a new context.', 'Look at two transplanted beds, one cared for and one left.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.GROWING_VEGETABLES.VEG_PRACTICES.M_AG5_VEG_HARVEST', 'AGRI.G5.FOOD_P.GROWING_VEGETABLES.VEG_PRACTICES', 'Thinks vegetables are harvested by uprooting the whole plant every time.', '{"question":"How are sukuma wiki leaves harvested?","wrong_answer":"Uproot the whole plant","correct_answer":"Pick the lower mature leaves and leave the plant to grow"}'::jsonb, 'The child has seen root crops pulled out and thinks all crops end at harvest.', 'Offer "Uproot the whole plant" next to the right answer and ask the question again in a new context.', 'Show a kale plant picked for weeks: the stem has scars of old leaves.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.GROWING_VEGETABLES.VEG_PRACTICES.M_AG5_VEG_MANURE', 'AGRI.G5.FOOD_P.GROWING_VEGETABLES.VEG_PRACTICES', 'Leaves out manure because vegetables are small plants that need little food.', '{"question":"Should manure be added when preparing a vegetable bed?","wrong_answer":"No, vegetables are small","correct_answer":"Yes, vegetables grow fast and need rich soil"}'::jsonb, 'The child judges a plant''s needs by its size.', 'Offer "No, vegetables are small" next to the right answer and ask the question again in a new context.', 'Grow kale in poor soil and in manured soil side by side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.GROWING_VEGETABLES.NURSERY_BED.M_AG5_NURS_SHADE', 'AGRI.G5.FOOD_P.GROWING_VEGETABLES.NURSERY_BED', 'Leaves the nursery bed in full sun with no shade.', '{"question":"Why is a nursery bed given shade?","wrong_answer":"It is not needed","correct_answer":"Young seedlings dry and scorch in strong sun"}'::jsonb, 'The child knows plants need sun and thinks more is always better.', 'Offer "It is not needed" next to the right answer and ask the question again in a new context.', 'Put one tray of seedlings in the sun and one under a shade for a hot day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.GROWING_VEGETABLES.SEEDLING_CARE.M_AG5_TRANS_SMALL', 'AGRI.G5.FOOD_P.GROWING_VEGETABLES.SEEDLING_CARE', 'Transplants seedlings as soon as they come up, with one leaf.', '{"question":"When are seedlings ready to transplant?","wrong_answer":"As soon as they come up","correct_answer":"When they have four to six true leaves and are hardened"}'::jsonb, 'The child thinks moving them early saves time.', 'Offer "As soon as they come up" next to the right answer and ask the question again in a new context.', 'Show a tiny and a ready seedling; ask which has the stronger roots.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_PRODUCTS.M_AG_PROD_COCK', 'AGRI.G5.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_PRODUCTS', 'Thinks a cock (or any chicken) can be the source of eggs or mixes hens and cocks.', '{"question":"Which bird lays the eggs we eat?","wrong_answer":"The cockerel","correct_answer":"The hen"}'::jsonb, 'The child uses chicken for both without separating them.', 'Offer "The cockerel" next to the right answer and ask the question again in a new context.', 'Ask the child to watch the flock: who sits on a nest?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_PRODUCTS.M_AG_PROD_WOOL', 'AGRI.G5.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_PRODUCTS', 'Thinks wool comes from goats (or that every animal gives every product).', '{"question":"Which animal gives wool?","wrong_answer":"A goat","correct_answer":"A sheep"}'::jsonb, 'The child treats sheep and goats as the same animal.', 'Offer "A goat" next to the right answer and ask the question again in a new context.', 'Show a sample of wool and a sample of goat skin and ask where each comes from.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_PRODUCTS.M_AG_PROD_MILK_ALL', 'AGRI.G5.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_PRODUCTS', 'Thinks every domestic animal gives milk.', '{"question":"Which of these does not give milk to the family?","wrong_answer":"A hen","correct_answer":"A cow"}'::jsonb, 'The child groups all farm animals together.', 'Offer "A hen" next to the right answer and ask the question again in a new context.', 'List the animals the family milks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_USES.M_AG_USE_FOOD_ONLY', 'AGRI.G5.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_USES', 'Thinks animals are kept only to be eaten.', '{"question":"Why does a farmer keep oxen?","wrong_answer":"Only for meat","correct_answer":"To pull the plough and the cart"}'::jsonb, 'The child sees animals through the plate.', 'Offer "Only for meat" next to the right answer and ask the question again in a new context.', 'Ask who ploughs the field in a family with no tractor.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_USES.M_AG_USE_DONKEY', 'AGRI.G5.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_USES', 'Thinks donkeys give milk or meat in the family (instead of carrying).', '{"question":"What is the main use of a donkey on many farms?","wrong_answer":"To give milk for tea","correct_answer":"To carry loads and pull a cart"}'::jsonb, 'The child gives the same use to all animals.', 'Offer "To give milk for tea" next to the right answer and ask the question again in a new context.', 'Ask who carries water in the dry season.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_USES.M_AG_USE_DUNG', 'AGRI.G5.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_USES', 'Thinks animal dung is just waste.', '{"question":"How can cow dung help a vegetable garden?","wrong_answer":"It cannot, it is only waste","correct_answer":"It rots into manure that feeds the soil"}'::jsonb, 'The child links dung with dirt.', 'Offer "It cannot, it is only waste" next to the right answer and ask the question again in a new context.', 'Compare kale grown with and without manure.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_PRODUCTS.M_AG5_PROD_HONEY', 'AGRI.G5.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_PRODUCTS', 'Thinks honey is made by flowers and bees only carry it.', '{"question":"Where does honey come from?","wrong_answer":"Flowers make it and bees carry it","correct_answer":"Bees make it from nectar they collect from flowers"}'::jsonb, 'The child knows flowers are involved and does not know the bees change nectar into honey.', 'Offer "Flowers make it and bees carry it" next to the right answer and ask the question again in a new context.', 'Show a honeycomb: the bees store and change the nectar inside it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_USES.M_AG5_USE_CAMEL', 'AGRI.G5.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_USES', 'Thinks camels are kept only for carrying loads.', '{"question":"What do camels give families in northern Kenya?","wrong_answer":"Only carrying","correct_answer":"Milk, meat and carrying"}'::jsonb, 'The child knows the camel only as a pack animal from pictures.', 'Offer "Only carrying" next to the right answer and ask the question again in a new context.', 'Show a picture of camel milk in a market in Isiolo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.PRESERVATION_OF_CEREALS_.PRESERVE_METHODS.M_AG_PRES_WET', 'AGRI.G5.FOOD_P.PRESERVATION_OF_CEREALS_.PRESERVE_METHODS', 'Stores grain while it is still damp.', '{"question":"Why must grain be dried before storing?","wrong_answer":"It stores better when damp","correct_answer":"Damp grain grows mould and rots"}'::jsonb, 'The child thinks wet grain is fresh.', 'Offer "It stores better when damp" next to the right answer and ask the question again in a new context.', 'Store a handful dry and a handful damp in jars for a week.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.PRESERVATION_OF_CEREALS_.PRESERVE_METHODS.M_AG_PRES_SACK', 'AGRI.G5.FOOD_P.PRESERVATION_OF_CEREALS_.PRESERVE_METHODS', 'Thinks a loosely tied or torn sack or polythene bag is good enough.', '{"question":"Which container keeps weevils from grain?","wrong_answer":"An open basket","correct_answer":"A tightly sealed container"}'::jsonb, 'The child thinks any container will do.', 'Offer "An open basket" next to the right answer and ask the question again in a new context.', 'Place weevils in an open jar and a sealed jar overnight.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.PRESERVATION_OF_CEREALS_.PRESERVE_METHODS.M_AG_PRES_WATER', 'AGRI.G5.FOOD_P.PRESERVATION_OF_CEREALS_.PRESERVE_METHODS', 'Thinks washing grain or keeping it in water preserves it.', '{"question":"Which is a way of preserving beans?","wrong_answer":"Soak them in water","correct_answer":"Dry them in the sun and store them in a sealed container"}'::jsonb, 'The child thinks wet keeps food fresh as with some vegetables.', 'Offer "Soak them in water" next to the right answer and ask the question again in a new context.', 'Ask what happens to soaked beans after a day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.PRESERVATION_OF_CEREALS_.PRESERVE_PRACTICE.M_AG_PRACT_SEAL_EARLY', 'AGRI.G5.FOOD_P.PRESERVATION_OF_CEREALS_.PRESERVE_PRACTICE', 'Seals the grain in a container as soon as it is harvested.', '{"question":"Maize is just harvested and still damp. What should be done before it is sealed?","wrong_answer":"Seal it at once","correct_answer":"Dry it in the sun until it is hard"}'::jsonb, 'The child thinks sealed means safe.', 'Offer "Seal it at once" next to the right answer and ask the question again in a new context.', 'Seal two jars, one with dry maize and one with damp, and look after a week.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.PRESERVATION_OF_CEREALS_.PRESERVE_PRACTICE.M_AG_PRACT_GROUND', 'AGRI.G5.FOOD_P.PRESERVATION_OF_CEREALS_.PRESERVE_PRACTICE', 'Stores sacks on the floor against the wall.', '{"question":"Where should sacks of grain be kept?","wrong_answer":"On the bare floor against the wall","correct_answer":"On a raised platform away from the wall"}'::jsonb, 'The child sees no reason to lift them.', 'Offer "On the bare floor against the wall" next to the right answer and ask the question again in a new context.', 'Ask where rats and damp enter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.PRESERVATION_OF_CEREALS_.PRESERVE_PRACTICE.M_AG_PRACT_DRYNESS', 'AGRI.G5.FOOD_P.PRESERVATION_OF_CEREALS_.PRESERVE_PRACTICE', 'Judges that grain is dry by looking at it or by how hot it felt.', '{"question":"How can you test that maize grains are dry?","wrong_answer":"Look at the colour","correct_answer":"Bite one and it cracks"}'::jsonb, 'The child has no feel for the test.', 'Offer "Look at the colour" next to the right answer and ask the question again in a new context.', 'Try the bite test on a dry and a damp grain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.PRESERVATION_OF_CEREALS_.PRESERVE_METHODS.M_AG5_PRES_ASH', 'AGRI.G5.FOOD_P.PRESERVATION_OF_CEREALS_.PRESERVE_METHODS', 'Thinks mixing grain with ash or storage dust is done to add flavour.', '{"question":"Why do some farmers mix stored beans with ash?","wrong_answer":"To make them taste better","correct_answer":"To keep weevils away"}'::jsonb, 'The child has seen ash mixed with food in other cooking and links it to taste.', 'Offer "To make them taste better" next to the right answer and ask the question again in a new context.', 'Show weevil holes in untreated beans next to beans stored with ash.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.PRESERVATION_OF_CEREALS_.PRESERVE_PRACTICE.M_AG5_PRACT_MIXOLD', 'AGRI.G5.FOOD_P.PRESERVATION_OF_CEREALS_.PRESERVE_PRACTICE', 'Pours the new harvest on top of last season''s grain in the store.', '{"question":"What should be done with old grain before storing the new harvest?","wrong_answer":"Pour the new grain on top","correct_answer":"Remove the old grain and clean the store first"}'::jsonb, 'The child thinks the store is simply a place to keep adding to.', 'Offer "Pour the new grain on top" next to the right answer and ask the question again in a new context.', 'Show weevils in old grain; ask where they go when new grain is poured on.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.FOOD_NUTRIENTS.NUTRIENT_FUNCTIONS.M_AG_NUT_PROT_ENERGY', 'AGRI.G5.FOOD_P.FOOD_NUTRIENTS.NUTRIENT_FUNCTIONS', 'Gives proteins the job of energy and carbohydrates the job of growth.', '{"question":"Which nutrient builds and repairs the body?","wrong_answer":"Carbohydrates","correct_answer":"Proteins"}'::jsonb, 'The child remembers only that ugali "fills".', 'Offer "Carbohydrates" next to the right answer and ask the question again in a new context.', 'Ask what a growing child needs to make new muscle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.FOOD_NUTRIENTS.NUTRIENT_FUNCTIONS.M_AG_NUT_VIT_ENERGY', 'AGRI.G5.FOOD_P.FOOD_NUTRIENTS.NUTRIENT_FUNCTIONS', 'Thinks vitamins give energy.', '{"question":"What do vitamins do in the body?","wrong_answer":"Give most of the energy","correct_answer":"Protect the body and help it stay healthy"}'::jsonb, 'The child links all nutrients with strength.', 'Offer "Give most of the energy" next to the right answer and ask the question again in a new context.', 'Ask which group of foods stops illness.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.FOOD_NUTRIENTS.NUTRIENT_FUNCTIONS.M_AG_NUT_FAT_BAD', 'AGRI.G5.FOOD_P.FOOD_NUTRIENTS.NUTRIENT_FUNCTIONS', 'Thinks fats do nothing useful.', '{"question":"What is one job of fats in the body?","wrong_answer":"They do nothing useful","correct_answer":"They store energy and keep the body warm"}'::jsonb, 'The child has only heard that too much fat is bad.', 'Offer "They do nothing useful" next to the right answer and ask the question again in a new context.', 'Ask why animals in cold places have a layer of fat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.FOOD_NUTRIENTS.FOOD_GROUPS.M_AG_GRP_PLANT_VIT', 'AGRI.G5.FOOD_P.FOOD_NUTRIENTS.FOOD_GROUPS', 'Thinks every plant food is rich in vitamins.', '{"question":"Which group is cassava in?","wrong_answer":"Foods that protect the body (vitamins)","correct_answer":"Energy foods (carbohydrates)"}'::jsonb, 'The child thinks plant means vitamin.', 'Offer "Foods that protect the body (vitamins)" next to the right answer and ask the question again in a new context.', 'Ask what ugali, rice and cassava have in common.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.FOOD_NUTRIENTS.FOOD_GROUPS.M_AG_GRP_MILK_ENERGY', 'AGRI.G5.FOOD_P.FOOD_NUTRIENTS.FOOD_GROUPS', 'Puts milk, eggs and beans among the energy foods.', '{"question":"Which group is an egg in?","wrong_answer":"Energy foods","correct_answer":"Body-building foods (proteins)"}'::jsonb, 'The child sees all filling food as energy.', 'Offer "Energy foods" next to the right answer and ask the question again in a new context.', 'Ask what chicks grow from.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.FOOD_NUTRIENTS.FOOD_GROUPS.M_AG_GRP_FILLING', 'AGRI.G5.FOOD_P.FOOD_NUTRIENTS.FOOD_GROUPS', 'Thinks a food that fills the stomach, such as ugali, is a body-building food.', '{"question":"Which group is ugali in?","wrong_answer":"Body-building foods (proteins)","correct_answer":"Energy foods (carbohydrates)"}'::jsonb, 'The child links a big plate with growing.', 'Offer "Body-building foods (proteins)" next to the right answer and ask the question again in a new context.', 'Ask what ugali is made from and what it gives for running and playing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.FOOD_NUTRIENTS.FOOD_GROUPS.M_AG_GRP_BUTTER_PROT', 'AGRI.G5.FOOD_P.FOOD_NUTRIENTS.FOOD_GROUPS', 'Thinks butter and cooking oil are proteins because they come from animals or seeds.', '{"question":"Which nutrient is cooking oil rich in?","wrong_answer":"Proteins","correct_answer":"Fats"}'::jsonb, 'The child thinks all animal and seed foods are protein.', 'Offer "Proteins" next to the right answer and ask the question again in a new context.', 'Ask what is left on the pan after frying.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.FOOD_NUTRIENTS.DEFICIENCY_DISEASES.M_AG_DIS_SWAP', 'AGRI.G5.FOOD_P.FOOD_NUTRIENTS.DEFICIENCY_DISEASES', 'Mixes up kwashiorkor and marasmus.', '{"question":"A very thin child with little muscle has had too little food overall. Which disease is this?","wrong_answer":"Kwashiorkor","correct_answer":"Marasmus"}'::jsonb, 'The child knows both are hunger diseases and has no detail.', 'Offer "Kwashiorkor" next to the right answer and ask the question again in a new context.', 'Describe the pictures: a swollen belly and puffy legs, and a very thin wasted child.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.FOOD_NUTRIENTS.DEFICIENCY_DISEASES.M_AG_DIS_CATCH', 'AGRI.G5.FOOD_P.FOOD_NUTRIENTS.DEFICIENCY_DISEASES', 'Thinks these diseases spread from person to person.', '{"question":"Can anaemia from lack of iron spread from one child to another?","wrong_answer":"Yes, through touch","correct_answer":"No, it comes from food that lacks iron"}'::jsonb, 'The child treats every illness as catching.', 'Offer "Yes, through touch" next to the right answer and ask the question again in a new context.', 'Ask what two children from the same home both ate and what they both missed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.FOOD_NUTRIENTS.DEFICIENCY_DISEASES.M_AG_DIS_CAUSE', 'AGRI.G5.FOOD_P.FOOD_NUTRIENTS.DEFICIENCY_DISEASES', 'Gives the wrong lack (anaemia from lack of calcium, goitre from lack of vitamins).', '{"question":"A swelling at the front of the neck can come from too little of which mineral?","wrong_answer":"Calcium","correct_answer":"Iodine"}'::jsonb, 'The child recalls that minerals matter but not which.', 'Offer "Calcium" next to the right answer and ask the question again in a new context.', 'Match each disease with its missing nutrient on a card.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.FOOD_NUTRIENTS.DISEASE_PREVENTION.M_AG_PREV_ONE_FOOD', 'AGRI.G5.FOOD_P.FOOD_NUTRIENTS.DISEASE_PREVENTION', 'Thinks eating much of one food (ugali) is enough.', '{"question":"Which meal protects a family best from nutritional diseases?","wrong_answer":"Only ugali, as much as they want","correct_answer":"Ugali with beans and sukuma wiki"}'::jsonb, 'The child thinks full means well fed.', 'Offer "Only ugali, as much as they want" next to the right answer and ask the question again in a new context.', 'Ask which nutrients ugali alone is missing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.FOOD_NUTRIENTS.DISEASE_PREVENTION.M_AG_PREV_SALT', 'AGRI.G5.FOOD_P.FOOD_NUTRIENTS.DISEASE_PREVENTION', 'Thinks any salt prevents goitre.', '{"question":"Which salt helps prevent goitre?","wrong_answer":"Any salt, even if it has no iodine","correct_answer":"Iodised salt"}'::jsonb, 'The child does not know iodised salt is different.', 'Offer "Any salt, even if it has no iodine" next to the right answer and ask the question again in a new context.', 'Check the packet for the word iodised.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.FOOD_NUTRIENTS.DISEASE_PREVENTION.M_AG_PREV_MEDICINE', 'AGRI.G5.FOOD_P.FOOD_NUTRIENTS.DISEASE_PREVENTION', 'Thinks only medicine, not food, prevents these diseases.', '{"question":"How is kwashiorkor best prevented?","wrong_answer":"Only with medicine","correct_answer":"With enough protein foods such as beans, eggs, milk and fish"}'::jsonb, 'The child links every health problem with medicine.', 'Offer "Only with medicine" next to the right answer and ask the question again in a new context.', 'Ask what a family can do at the next meal.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.FOOD_NUTRIENTS.NUTRIENT_FUNCTIONS.M_AG5_NUT_WATER', 'AGRI.G5.FOOD_P.FOOD_NUTRIENTS.NUTRIENT_FUNCTIONS', 'Leaves water out of what the body needs from food and drink.', '{"question":"Why does the body need water?","wrong_answer":"It does not; only food matters","correct_answer":"To carry food and waste, cool the body and help digestion"}'::jsonb, 'The child thinks of water as a drink, not as part of a healthy diet.', 'Offer "It does not; only food matters" next to the right answer and ask the question again in a new context.', 'Ask how you feel after games on a hot day with no water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.FOOD_NUTRIENTS.DEFICIENCY_DISEASES.M_AG5_DIS_RICKETS', 'AGRI.G5.FOOD_P.FOOD_NUTRIENTS.DEFICIENCY_DISEASES', 'Thinks rickets (soft, bent leg bones) is caused by walking too early.', '{"question":"What causes rickets?","wrong_answer":"Walking too early","correct_answer":"Too little vitamin D and calcium (sunlight, milk, small fish)"}'::jsonb, 'The child sees bent legs and links them to how the child walks.', 'Offer "Walking too early" next to the right answer and ask the question again in a new context.', 'Show which foods and what sunlight build strong bones.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.FOOD_NUTRIENTS.DISEASE_PREVENTION.M_AG5_PREV_SWEETS', 'AGRI.G5.FOOD_P.FOOD_NUTRIENTS.DISEASE_PREVENTION', 'Thinks sweets and soda give the body what it needs to stay healthy because they give energy.', '{"question":"Do sweets and soda prevent nutritional diseases?","wrong_answer":"Yes, they give energy","correct_answer":"No, they give sugar but almost none of the other nutrients"}'::jsonb, 'The child knows sugar gives energy and thinks energy is all the body needs.', 'Offer "Yes, they give energy" next to the right answer and ask the question again in a new context.', 'Compare a soda with milk on a nutrient chart: which has protein and calcium?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.COOKING_FOOD.FRYING_METHODS.M_AG_FRY_DEEP_LITTLE', 'AGRI.G5.FOOD_P.COOKING_FOOD.FRYING_METHODS', 'Thinks deep frying uses only a little oil.', '{"question":"How much oil does deep frying use?","wrong_answer":"A spoonful","correct_answer":"Enough to cover the food completely"}'::jsonb, 'The child mixes deep and shallow frying.', 'Offer "A spoonful" next to the right answer and ask the question again in a new context.', 'Compare a pan of mandazi frying in deep oil and eggs frying in a little oil.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.COOKING_FOOD.FRYING_METHODS.M_AG_FRY_DRY_LOTS', 'AGRI.G5.FOOD_P.COOKING_FOOD.FRYING_METHODS', 'Thinks dry fat frying needs much added oil.', '{"question":"Sausages are cooked in a pan with no added oil. Which method is this?","wrong_answer":"Deep frying","correct_answer":"Dry fat frying"}'::jsonb, 'The child thinks all frying uses oil.', 'Offer "Deep frying" next to the right answer and ask the question again in a new context.', 'Warm sausages in a dry pan and watch the fat come out.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.COOKING_FOOD.FRYING_METHODS.M_AG_FRY_MIX', 'AGRI.G5.FOOD_P.COOKING_FOOD.FRYING_METHODS', 'Mixes up the foods (mandazi and chips as dry fat frying, sausages as deep frying).', '{"question":"Which food is usually deep fried?","wrong_answer":"Sausages","correct_answer":"Mandazi"}'::jsonb, 'The child names the method from the food, not from how it is cooked.', 'Offer "Sausages" next to the right answer and ask the question again in a new context.', 'Ask whether the food floats in oil or cooks in its own fat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.COOKING_FOOD.FRYING_SAFETY.M_AG_FSAFE_WATER', 'AGRI.G5.FOOD_P.COOKING_FOOD.FRYING_SAFETY', 'Throws water on a burning pan of oil.', '{"question":"A pan of oil catches fire. What do you do?","wrong_answer":"Pour water on it","correct_answer":"Cover it with a lid and turn off the heat"}'::jsonb, 'The child thinks water puts out every fire.', 'Offer "Pour water on it" next to the right answer and ask the question again in a new context.', 'Show with a teacher why water and hot oil spit and spread the fire.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.COOKING_FOOD.FRYING_SAFETY.M_AG_FSAFE_WET', 'AGRI.G5.FOOD_P.COOKING_FOOD.FRYING_SAFETY', 'Puts wet food into hot oil.', '{"question":"Why should food be dry before it goes into hot oil?","wrong_answer":"Water in the oil makes no difference","correct_answer":"Water makes the hot oil spit and can burn you"}'::jsonb, 'The child washed the food and goes straight to the pan.', 'Offer "Water in the oil makes no difference" next to the right answer and ask the question again in a new context.', 'Dry one piece and leave another wet, drop each into a safe test with a teacher.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.COOKING_FOOD.FRYING_SAFETY.M_AG_FSAFE_FULL', 'AGRI.G5.FOOD_P.COOKING_FOOD.FRYING_SAFETY', 'Fills the pan to the top with oil.', '{"question":"How full should the pan be for deep frying?","wrong_answer":"Right to the top","correct_answer":"No more than half full"}'::jsonb, 'The child thinks more oil is safer.', 'Offer "Right to the top" next to the right answer and ask the question again in a new context.', 'Ask what happens when food goes into a full pan.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.COOKING_FOOD.FRYING_SAFETY.M_AG_FSAFE_LEAVE', 'AGRI.G5.FOOD_P.COOKING_FOOD.FRYING_SAFETY', 'Leaves the pan of hot oil to do something else.', '{"question":"Hot oil is on the stove and the phone rings. What do you do?","wrong_answer":"Go and answer, the oil will wait","correct_answer":"Turn off the heat first, or stay at the stove"}'::jsonb, 'The child thinks frying is slow.', 'Offer "Go and answer, the oil will wait" next to the right answer and ask the question again in a new context.', 'Ask how fast oil heats and when it smokes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.FOOD_P.COOKING_FOOD.FRYING_METHODS.M_AG5_FRY_COLDOIL', 'AGRI.G5.FOOD_P.COOKING_FOOD.FRYING_METHODS', 'Puts food into cold oil and heats them together for deep frying.', '{"question":"When is food put into the oil for deep frying?","wrong_answer":"Into cold oil, then heat","correct_answer":"When the oil is hot enough"}'::jsonb, 'The child does not know cold oil soaks into the food.', 'Offer "Into cold oil, then heat" next to the right answer and ask the question again in a new context.', 'Compare a piece fried from cold oil (greasy) with one put into hot oil (crisp).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.HYGIEN.GOOD_GROOMING_PRACTICES.GROOMING_HABITS.M_AG_GROOM_EXPENSIVE', 'AGRI.G5.HYGIEN.GOOD_GROOMING_PRACTICES.GROOMING_HABITS', 'Thinks good grooming needs expensive clothes or soaps.', '{"question":"Which is part of good grooming?","wrong_answer":"Wearing the most expensive clothes","correct_answer":"Bathing daily and wearing clean clothes"}'::jsonb, 'The child links neat with rich.', 'Offer "Wearing the most expensive clothes" next to the right answer and ask the question again in a new context.', 'Ask whether a clean old shirt is good grooming.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.HYGIEN.GOOD_GROOMING_PRACTICES.GROOMING_HABITS.M_AG_GROOM_PERFUME', 'AGRI.G5.HYGIEN.GOOD_GROOMING_PRACTICES.GROOMING_HABITS', 'Thinks perfume or powder can replace bathing.', '{"question":"Which keeps a child healthy and fresh?","wrong_answer":"Perfume without bathing","correct_answer":"Bathing with soap and water"}'::jsonb, 'The child has seen adults use scent.', 'Offer "Perfume without bathing" next to the right answer and ask the question again in a new context.', 'Ask what scent covers and what soap removes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.HYGIEN.GOOD_GROOMING_PRACTICES.GROOMING_HABITS.M_AG_GROOM_SPECIAL', 'AGRI.G5.HYGIEN.GOOD_GROOMING_PRACTICES.GROOMING_HABITS', 'Thinks grooming is only for special days.', '{"question":"How often should a child brush teeth and bathe?","wrong_answer":"Only on special days","correct_answer":"Every day"}'::jsonb, 'The child links grooming with parties.', 'Offer "Only on special days" next to the right answer and ask the question again in a new context.', 'Ask when germs gather.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.HYGIEN.GOOD_GROOMING_PRACTICES.DRESS_ETIQUETTE.M_AG_DRESS_SAME', 'AGRI.G5.HYGIEN.GOOD_GROOMING_PRACTICES.DRESS_ETIQUETTE', 'Thinks one kind of clothing suits every place and activity.', '{"question":"What is best to wear for farm work at school?","wrong_answer":"Your best clothes","correct_answer":"Old clothes with gumboots and an apron"}'::jsonb, 'The child does not match dress to the job and thinks neat means best clothes.', 'Offer "Your best clothes" next to the right answer and ask the question again in a new context.', 'Ask what happens to best clothes in the mud, and what a games kit is for.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.HYGIEN.GOOD_GROOMING_PRACTICES.DRESS_ETIQUETTE.M_AG_ETIQ_GREET', 'AGRI.G5.HYGIEN.GOOD_GROOMING_PRACTICES.DRESS_ETIQUETTE', 'Thinks greeting and polite words are only for people one knows or for the old.', '{"question":"A visitor comes to school. What is good manners?","wrong_answer":"Ignore her, she is a stranger","correct_answer":"Greet her politely"}'::jsonb, 'The child is shy, or has been taught not to speak to strangers and mixes this up with manners at school.', 'Offer "Ignore her, she is a stranger" next to the right answer and ask the question again in a new context.', 'Practise a greeting for a visitor in class, then ask how the visitor would feel with no greeting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.HYGIEN.GOOD_GROOMING_PRACTICES.GROOMING_HABITS.M_AG5_GROOM_HAIR', 'AGRI.G5.HYGIEN.GOOD_GROOMING_PRACTICES.GROOMING_HABITS', 'Thinks hair only needs combing for school photos and visits.', '{"question":"How often should hair be combed or brushed?","wrong_answer":"Only on special days","correct_answer":"Every day"}'::jsonb, 'The child links grooming with being seen by visitors.', 'Offer "Only on special days" next to the right answer and ask the question again in a new context.', 'Ask what happens to uncombed hair over a week: tangles, dirt, lice.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.HYGIEN.GOOD_GROOMING_PRACTICES.DRESS_ETIQUETTE.M_AG5_DRESS_GARDEN', 'AGRI.G5.HYGIEN.GOOD_GROOMING_PRACTICES.DRESS_ETIQUETTE', 'Wears school or best clothes for digging in the garden.', '{"question":"What should you wear for gardening?","wrong_answer":"My best school uniform","correct_answer":"Old clothes or an overall, and gumboots"}'::jsonb, 'The child thinks neat means wearing the best clothes for everything.', 'Offer "My best school uniform" next to the right answer and ask the question again in a new context.', 'Show a uniform after a gardening lesson.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.HYGIEN.GOOD_GROOMING_PRACTICES.DRESS_ETIQUETTE.M_AG5_ETIQ_EAT', 'AGRI.G5.HYGIEN.GOOD_GROOMING_PRACTICES.DRESS_ETIQUETTE', 'Talks with food in the mouth and reaches across the table.', '{"question":"Which is good table manners?","wrong_answer":"Talking with a full mouth","correct_answer":"Chewing with the mouth closed and asking for food to be passed"}'::jsonb, 'The child eats at home without thinking about others at the table.', 'Offer "Talking with a full mouth" next to the right answer and ask the question again in a new context.', 'Act out two meals and ask which is pleasant to sit next to.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.HYGIEN.HOME_HYGIENE.SURFACE_TYPES.M_AG_SURF_TILE_CEMENT', 'AGRI.G5.HYGIEN.HOME_HYGIENE.SURFACE_TYPES', 'Mixes up a cemented floor and a tiled floor.', '{"question":"A floor is made of smooth shiny squares laid side by side. What is it?","wrong_answer":"A cemented floor","correct_answer":"A tiled floor"}'::jsonb, 'Both are hard and cool, and the child has not touched both.', 'Offer "A cemented floor" next to the right answer and ask the question again in a new context.', 'Let the child feel a piece of rough cement and a glazed tile and say which is which.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.HYGIEN.HOME_HYGIENE.SURFACE_TYPES.M_AG_SURF_TILE_GLASS', 'AGRI.G5.HYGIEN.HOME_HYGIENE.SURFACE_TYPES', 'Thinks a shiny surface must be glass (or a see-through one is wood or tile).', '{"question":"A window pane is see-through and smooth. What is it made of?","wrong_answer":"Wood","correct_answer":"Glass"}'::jsonb, 'The child links shine with glass and ignores the test of seeing through.', 'Offer "Wood" next to the right answer and ask the question again in a new context.', 'Hold each material up to the light and ask which lets the light through.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.HYGIEN.HOME_HYGIENE.SURFACE_CLEANING.M_AG_CLEAN_SOAK_WOOD', 'AGRI.G5.HYGIEN.HOME_HYGIENE.SURFACE_CLEANING', 'Soaks or floods wooden things with water.', '{"question":"How should a wooden table be cleaned?","wrong_answer":"Pour lots of water on it","correct_answer":"Wipe it with a damp cloth and dry it"}'::jsonb, 'The child thinks water cleans every surface.', 'Offer "Pour lots of water on it" next to the right answer and ask the question again in a new context.', 'Compare a piece of wood soaked overnight with a piece wiped damp, after a day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.HYGIEN.HOME_HYGIENE.SURFACE_CLEANING.M_AG_CLEAN_EARTH_SCRUB', 'AGRI.G5.HYGIEN.HOME_HYGIENE.SURFACE_CLEANING', 'Scrubs an earthen floor with plenty of water (as for cement).', '{"question":"How is an earthen floor cleaned?","wrong_answer":"Scrub it with plenty of water","correct_answer":"Sprinkle a little water and sweep softly"}'::jsonb, 'The child uses the cement method for every floor.', 'Offer "Scrub it with plenty of water" next to the right answer and ask the question again in a new context.', 'Ask what plenty of water does to packed soil.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.HYGIEN.HOME_HYGIENE.SURFACE_CLEANING.M_AG_CLEAN_WET_SLIP', 'AGRI.G5.HYGIEN.HOME_HYGIENE.SURFACE_CLEANING', 'Leaves a tiled floor wet after mopping.', '{"question":"After mopping the tiles, what must be done?","wrong_answer":"Leave them wet","correct_answer":"Dry them so that no one slips"}'::jsonb, 'The child thinks wet means clean and has not thought about slipping.', 'Offer "Leave them wet" next to the right answer and ask the question again in a new context.', 'Walk carefully on a wet tile and a dry tile, and ask which is safer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.HYGIEN.HOME_HYGIENE.SURFACE_CLEANING.M_AG_CLEAN_WASH_FIRST', 'AGRI.G5.HYGIEN.HOME_HYGIENE.SURFACE_CLEANING', 'Washes a floor before sweeping or dusting it.', '{"question":"What comes first in cleaning a cemented floor?","wrong_answer":"Scrub it with water","correct_answer":"Sweep away the dust"}'::jsonb, 'The child goes straight to water, as washing seems the real cleaning.', 'Offer "Scrub it with water" next to the right answer and ask the question again in a new context.', 'Pour water on a dusty floor and look at the mud, then sweep first and try again.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.HYGIEN.HOME_HYGIENE.SURFACE_TYPES.M_AG5_SURF_PLASTIC', 'AGRI.G5.HYGIEN.HOME_HYGIENE.SURFACE_TYPES', 'Thinks a plastic table is made of wood because it is coloured brown.', '{"question":"A brown table is light, smooth and bends a little. What is it made of?","wrong_answer":"Wood, because it is brown","correct_answer":"Plastic"}'::jsonb, 'The child names the material from its colour.', 'Offer "Wood, because it is brown" next to the right answer and ask the question again in a new context.', 'Tap a plastic and a wooden table; feel the weight and grain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.HYGIEN.HOME_HYGIENE.SURFACE_TYPES.M_AG5_SURF_EARTH', 'AGRI.G5.HYGIEN.HOME_HYGIENE.SURFACE_TYPES', 'Thinks an earthen floor is just dirt that cannot be cleaned.', '{"question":"Can an earthen floor be kept clean?","wrong_answer":"No, it is only dirt","correct_answer":"Yes, by sweeping and smearing it"}'::jsonb, 'The child thinks only hard floors count as clean surfaces.', 'Offer "No, it is only dirt" next to the right answer and ask the question again in a new context.', 'Show a smeared earthen floor in a rural home: smooth and swept.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.HYGIEN.LAUNDERING_COTTON_ITEM.LAUNDRY_STEPS.M_AG_LAUN_ORDER', 'AGRI.G5.HYGIEN.LAUNDERING_COTTON_ITEM.LAUNDRY_STEPS', 'Puts the laundry steps in the wrong order (ironing before washing, drying before rinsing).', '{"question":"Which comes first in laundering clothes?","wrong_answer":"Ironing them","correct_answer":"Sorting the clothes"}'::jsonb, 'The child has not seen the whole job done in order.', 'Offer "Ironing them" next to the right answer and ask the question again in a new context.', 'Lay out the steps on cards and do a real small wash in that order.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.HYGIEN.LAUNDERING_COTTON_ITEM.LAUNDRY_STEPS.M_AG_LAUN_MIX', 'AGRI.G5.HYGIEN.LAUNDERING_COTTON_ITEM.LAUNDRY_STEPS', 'Washes white and coloured clothes together.', '{"question":"Why wash white and coloured clothes separately?","wrong_answer":"There is no reason","correct_answer":"Colour can run and stain the white ones"}'::jsonb, 'The child wants to save water and soap and has not seen colour run.', 'Offer "There is no reason" next to the right answer and ask the question again in a new context.', 'Soak a red cloth with a white one in a basin and look at the water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.HYGIEN.LAUNDERING_COTTON_ITEM.LAUNDRY_STEPS.M_AG_LAUN_RINSE', 'AGRI.G5.HYGIEN.LAUNDERING_COTTON_ITEM.LAUNDRY_STEPS', 'Skips or rushes the rinse and leaves soap in the cloth.', '{"question":"What happens if soap is left in clothes?","wrong_answer":"Nothing","correct_answer":"They stay stiff and can make the skin itch"}'::jsonb, 'The child thinks soap in the cloth keeps it clean.', 'Offer "Nothing" next to the right answer and ask the question again in a new context.', 'Feel a rinsed and an unrinsed cloth when dry.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.HYGIEN.LAUNDERING_COTTON_ITEM.LAUNDRY_CARE.M_AG_CARE_HOT', 'AGRI.G5.HYGIEN.LAUNDERING_COTTON_ITEM.LAUNDRY_CARE', 'Uses very hot water on coloured clothes.', '{"question":"What is best for washing coloured cotton?","wrong_answer":"Very hot water","correct_answer":"Cool or warm water"}'::jsonb, 'The child thinks hotter water always cleans better.', 'Offer "Very hot water" next to the right answer and ask the question again in a new context.', 'Wash two cloths of the same colour, one in cool and one in hot water, and look at the water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.HYGIEN.LAUNDERING_COTTON_ITEM.LAUNDRY_CARE.M_AG_CARE_SUN', 'AGRI.G5.HYGIEN.LAUNDERING_COTTON_ITEM.LAUNDRY_CARE', 'Dries coloured clothes face out in strong sun.', '{"question":"How should coloured clothes be dried?","wrong_answer":"Face out in the hot sun","correct_answer":"Inside out in the shade"}'::jsonb, 'The child dries all clothes the same way and has seen white clothes dried in the sun.', 'Offer "Face out in the hot sun" next to the right answer and ask the question again in a new context.', 'Compare an old shirt dried face out in the sun for a term with a shirt dried in the shade.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.HYGIEN.LAUNDERING_COTTON_ITEM.LAUNDRY_CARE.M_AG_CARE_IRON', 'AGRI.G5.HYGIEN.LAUNDERING_COTTON_ITEM.LAUNDRY_CARE', 'Irons cotton on a cool setting, or when soaking wet or bone dry.', '{"question":"How is cotton ironed?","wrong_answer":"With a cool iron when soaking wet","correct_answer":"With a hot iron while a little damp"}'::jsonb, 'The child fears burning the cloth.', 'Offer "With a cool iron when soaking wet" next to the right answer and ask the question again in a new context.', 'Iron two pieces of cotton, one dripping and one a little damp, with a teacher.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.HYGIEN.LAUNDERING_COTTON_ITEM.LAUNDRY_STEPS.M_AG5_LAUN_SORT', 'AGRI.G5.HYGIEN.LAUNDERING_COTTON_ITEM.LAUNDRY_STEPS', 'Skips sorting and mending, and goes straight to soaking.', '{"question":"What is the first step in laundering?","wrong_answer":"Soak everything together","correct_answer":"Sort the clothes and mend any tears"}'::jsonb, 'The child thinks washing starts with water.', 'Offer "Soak everything together" next to the right answer and ask the question again in a new context.', 'Show a small tear that became a big hole after washing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.HYGIEN.LAUNDERING_COTTON_ITEM.LAUNDRY_CARE.M_AG5_CARE_WRING', 'AGRI.G5.HYGIEN.LAUNDERING_COTTON_ITEM.LAUNDRY_CARE', 'Twists and wrings coloured cotton hard to dry it fast.', '{"question":"How should a coloured cotton shirt be squeezed after rinsing?","wrong_answer":"Twist it as hard as possible","correct_answer":"Squeeze gently or fold and press"}'::jsonb, 'The child thinks harder wringing dries faster with no harm.', 'Offer "Twist it as hard as possible" next to the right answer and ask the question again in a new context.', 'Compare a shirt wrung hard (creased, stretched) with one squeezed gently.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.PRODUC.REPAIRING_GARMENTS.STITCH_TYPES.M_AG_STITCH_SWAP', 'AGRI.G5.PRODUC.REPAIRING_GARMENTS.STITCH_TYPES', 'Swaps the names or the look of running stitch and back stitch.', '{"question":"Which stitch goes back to meet the last stitch, leaving no gap?","wrong_answer":"Running stitch","correct_answer":"Back stitch"}'::jsonb, 'The child knows the names but not the picture they make on the cloth.', 'Offer "Running stitch" next to the right answer and ask the question again in a new context.', 'Have the child sew a short line of each on a scrap of cloth and name them from the pattern.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.PRODUC.REPAIRING_GARMENTS.STITCH_TYPES.M_AG_STITCH_RUN_STRONG', 'AGRI.G5.PRODUC.REPAIRING_GARMENTS.STITCH_TYPES', 'Thinks running stitch is the strongest because it is quick and long.', '{"question":"Which stitch is stronger?","wrong_answer":"Running stitch","correct_answer":"Back stitch"}'::jsonb, 'The child thinks that the quickest stitch must be the best.', 'Offer "Running stitch" next to the right answer and ask the question again in a new context.', 'Pull two seams, one in each stitch, and see which gives way.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.PRODUC.REPAIRING_GARMENTS.STITCH_TYPES.M_AG_STITCH_BACK_GAPS', 'AGRI.G5.PRODUC.REPAIRING_GARMENTS.STITCH_TYPES', 'Thinks back stitch leaves gaps (and running stitch does not).', '{"question":"Which stitch leaves gaps between stitches on the front?","wrong_answer":"Back stitch","correct_answer":"Running stitch"}'::jsonb, 'The child mixes the two pictures.', 'Offer "Back stitch" next to the right answer and ask the question again in a new context.', 'Look at the front of both stitches on a scrap and count the gaps.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.PRODUC.REPAIRING_GARMENTS.SEAM_REPAIR.M_AG_SEAM_RUN', 'AGRI.G5.PRODUC.REPAIRING_GARMENTS.SEAM_REPAIR', 'Uses running stitch to repair a gaping seam because it is quicker.', '{"question":"Which stitch repairs a gaping seam?","wrong_answer":"Running stitch","correct_answer":"Back stitch"}'::jsonb, 'The child chooses the stitch that is quickest to sew.', 'Offer "Running stitch" next to the right answer and ask the question again in a new context.', 'Repair two seams, one in each stitch, and pull them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.PRODUC.REPAIRING_GARMENTS.SEAM_REPAIR.M_AG_SEAM_START', 'AGRI.G5.PRODUC.REPAIRING_GARMENTS.SEAM_REPAIR', 'Starts exactly at the gap and stops at its end, without securing the thread.', '{"question":"Where should the repair of a gaping seam start?","wrong_answer":"Exactly at the first gap","correct_answer":"A little before the gap on the sound seam"}'::jsonb, 'The child sews only the gap and not the cloth around it.', 'Offer "Exactly at the first gap" next to the right answer and ask the question again in a new context.', 'Pull a seam that started at the gap and one that started before it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.PRODUC.REPAIRING_GARMENTS.SEAM_REPAIR.M_AG_SEAM_TIGHT', 'AGRI.G5.PRODUC.REPAIRING_GARMENTS.SEAM_REPAIR', 'Pulls the thread as tight as possible.', '{"question":"How tight should the thread be pulled?","wrong_answer":"As tight as possible","correct_answer":"Firm but not puckering the cloth"}'::jsonb, 'The child believes tight means strong.', 'Offer "As tight as possible" next to the right answer and ask the question again in a new context.', 'Look at a puckered seam and a flat seam side by side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.PRODUC.REPAIRING_GARMENTS.STITCH_TYPES.M_AG5_STITCH_TACK', 'AGRI.G5.PRODUC.REPAIRING_GARMENTS.STITCH_TYPES', 'Thinks running stitch and tacking are exactly the same and both are taken out.', '{"question":"How is running stitch different from tacking?","wrong_answer":"They are the same and both are removed","correct_answer":"Running stitch is smaller and stays in; tacking is long and is removed"}'::jsonb, 'The child sees the same in-and-out movement.', 'Offer "They are the same and both are removed" next to the right answer and ask the question again in a new context.', 'Lay a tacking sample beside a running stitch sample and measure the stitches.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.PRODUC.REPAIRING_GARMENTS.SEAM_REPAIR.M_AG5_SEAM_RIGHT', 'AGRI.G5.PRODUC.REPAIRING_GARMENTS.SEAM_REPAIR', 'Repairs the seam on the right side of the garment so the stitches show.', '{"question":"Which side of the garment is a seam repaired from?","wrong_answer":"The right side, where it shows","correct_answer":"The wrong side, along the old seam line"}'::jsonb, 'The child works where the hole is seen.', 'Offer "The right side, where it shows" next to the right answer and ask the question again in a new context.', 'Turn a shirt inside out and show the old seam line to follow.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.PRODUC.CONSTRUCTING_INNOVATIVE_.GARDEN_TYPES.M_AG_GTYPE_NEED_LAND', 'AGRI.G5.PRODUC.CONSTRUCTING_INNOVATIVE_.GARDEN_TYPES', 'Thinks a vertical garden needs more land than a flat one.', '{"question":"Which kind of garden needs the least ground?","wrong_answer":"A horizontal garden","correct_answer":"A vertical garden"}'::jsonb, 'The child thinks vertical means bigger.', 'Offer "A horizontal garden" next to the right answer and ask the question again in a new context.', 'Stand a sack on the ground and measure the ground it covers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.PRODUC.CONSTRUCTING_INNOVATIVE_.GARDEN_TYPES.M_AG_GTYPE_SWAP', 'AGRI.G5.PRODUC.CONSTRUCTING_INNOVATIVE_.GARDEN_TYPES', 'Calls a sack garden horizontal, or a flat bed vertical.', '{"question":"A sack garden is which kind of garden?","wrong_answer":"Horizontal","correct_answer":"Vertical"}'::jsonb, 'The child mixes the two words and does not picture the direction.', 'Offer "Horizontal" next to the right answer and ask the question again in a new context.', 'Stand a sack up and lay a tray flat and name each one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.PRODUC.CONSTRUCTING_INNOVATIVE_.GARDEN_BUILD.M_AG_GBUILD_ANY_CROP', 'AGRI.G5.PRODUC.CONSTRUCTING_INNOVATIVE_.GARDEN_BUILD', 'Thinks any crop (maize, cassava) will grow in a sack or bottle garden.', '{"question":"Which crop suits a sack garden?","wrong_answer":"Maize","correct_answer":"Kale"}'::jsonb, 'The child thinks a sack garden is simply a small field.', 'Offer "Maize" next to the right answer and ask the question again in a new context.', 'Ask how deep the roots of maize and cassava go compared with kale.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.PRODUC.CONSTRUCTING_INNOVATIVE_.GARDEN_BUILD.M_AG_GBUILD_DRAIN', 'AGRI.G5.PRODUC.CONSTRUCTING_INNOVATIVE_.GARDEN_BUILD', 'Leaves out drainage holes or the stone column, so the water does not move through the soil.', '{"question":"Why is a column of stones placed in the middle of a sack garden?","wrong_answer":"For decoration only","correct_answer":"To let water reach the lower soil"}'::jsonb, 'The child sees the stones as a weight and not as a water path.', 'Offer "For decoration only" next to the right answer and ask the question again in a new context.', 'Pour water into one sack with a column and one without, then open them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.PRODUC.CONSTRUCTING_INNOVATIVE_.GARDEN_BUILD.M_AG_GBUILD_NO_WATER', 'AGRI.G5.PRODUC.CONSTRUCTING_INNOVATIVE_.GARDEN_BUILD', 'Thinks a vertical garden needs no watering.', '{"question":"How often does a sack garden need water?","wrong_answer":"Never, the sack keeps it","correct_answer":"Regularly, through the stone column"}'::jsonb, 'The child thinks soil in a sack stays damp for ever.', 'Offer "Never, the sack keeps it" next to the right answer and ask the question again in a new context.', 'Feel the soil of a sack garden two days after watering.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.PRODUC.CONSTRUCTING_INNOVATIVE_.GARDEN_TYPES.M_AG5_GTYPE_TOWN', 'AGRI.G5.PRODUC.CONSTRUCTING_INNOVATIVE_.GARDEN_TYPES', 'Thinks innovative gardens are only for towns.', '{"question":"Who can use a sack garden?","wrong_answer":"Only people in towns","correct_answer":"Anyone with little space, water or good soil, in town or village"}'::jsonb, 'The child has seen sack gardens in town pictures only.', 'Offer "Only people in towns" next to the right answer and ask the question again in a new context.', 'Ask where a village school with rocky ground could grow kale.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.PRODUC.CONSTRUCTING_INNOVATIVE_.GARDEN_TYPES.M_AG5_GTYPE_TYRE', 'AGRI.G5.PRODUC.CONSTRUCTING_INNOVATIVE_.GARDEN_TYPES', 'Thinks a tyre garden is vertical because tyres stand up.', '{"question":"Old tyres laid flat on the ground and filled with soil make which garden?","wrong_answer":"Vertical","correct_answer":"Horizontal"}'::jsonb, 'The child knows tyres can stand upright and does not look at how they are laid.', 'Offer "Vertical" next to the right answer and ask the question again in a new context.', 'Lay a tyre flat and one stacked in a tower; ask which grows upwards.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G5.PRODUC.CONSTRUCTING_INNOVATIVE_.GARDEN_BUILD.M_AG5_GBUILD_SUN', 'AGRI.G5.PRODUC.CONSTRUCTING_INNOVATIVE_.GARDEN_BUILD', 'Puts the innovative garden in deep shade behind a building.', '{"question":"Where should a sack garden be placed?","wrong_answer":"In deep shade behind a wall","correct_answer":"Where it gets sunlight for most of the day, near water"}'::jsonb, 'The child thinks shade keeps the soil damp and so is best.', 'Offer "In deep shade behind a wall" next to the right answer and ask the question again in a new context.', 'Grow kale in one sack in shade and one in sun for three weeks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
